<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('security.view');$t=(int)$user['tenant_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$sql="UPDATE user_sessions SET revoked_at=NOW() WHERE id=:id AND tenant_id=:t AND revoked_at IS NULL";$p=['id'=>$id,'t'=>$t];if(!\App\Core\Rbac::allows((int)$user['id'],'security.manage')){$sql.=' AND user_id=:u';$p['u']=$user['id'];}$st=db()->prepare($sql);$st->execute($p);audit('security.session_revoke','user_session',$id,[]);flash('success','Sessão revogada.');redirect('security/index.php');}$sql="SELECT s.*,u.name user_name,u.email FROM user_sessions s JOIN users u ON u.id=s.user_id AND u.tenant_id=s.tenant_id WHERE s.tenant_id=:t";$p=['t'=>$t];if(!\App\Core\Rbac::allows((int)$user['id'],'security.manage')){$sql.=' AND s.user_id=:u';$p['u']=$user['id'];}$sql.=' ORDER BY s.created_at DESC LIMIT 100';$st=db()->prepare($sql);$st->execute($p);$sessions=$st->fetchAll();$st=db()->prepare("SELECT * FROM audit_logs WHERE tenant_id=:t ".(\App\Core\Rbac::allows((int)$user['id'],'security.manage')?'':'AND user_id=:u ')."ORDER BY id DESC LIMIT 60");$pa=['t'=>$t];if(!\App\Core\Rbac::allows((int)$user['id'],'security.manage'))$pa['u']=$user['id'];$st->execute($pa);$logs=$st->fetchAll();layout('Segurança',function()use($sessions,$logs,$user){?><div class="page-head"><div><span class="eyebrow">Segurança</span><h1>Sessões e auditoria</h1><p>Revogue dispositivos e acompanhe eventos registrados na cadeia de auditoria.</p></div></div><section class="card"><h2>Sessões</h2><div class="table-wrap"><table class="table"><thead><tr><th>Usuário</th><th>IP</th><th>Dispositivo</th><th>Última atividade</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($sessions as $s):?><tr><td><?=e($s['user_name'])?></td><td><?=e($s['ip_address'])?></td><td title="<?=e($s['user_agent'])?>"><?=e(mb_substr($s['user_agent']??'',0,45))?></td><td><?=e($s['last_seen_at']?date('d/m H:i',strtotime($s['last_seen_at'])):'—')?></td><td><span class="status <?=$s['revoked_at']?'suspended':'active'?>"><?=$s['revoked_at']?'revogada':'ativa'?></span></td><td><?php if(!$s['revoked_at']):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$s['id']?>"><button class="button ghost small">Revogar</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div></section><section class="card" style="margin-top:18px"><h2>Auditoria recente</h2><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Ação</th><th>Entidade</th><th>IP</th><th>Hash</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=e(date('d/m H:i:s',strtotime($l['created_at'])))?></td><td><?=e($l['action'])?></td><td><?=e($l['entity_type'])?> #<?=e($l['entity_id']?:'—')?></td><td><?=e($l['ip_address'])?></td><td><code><?=e(substr($l['event_hash'],0,12))?>…</code></td></tr><?php endforeach?></tbody></table></div></section><?php },['active'=>'security']);
